use super::{ffi,DirectEditor};use crate::theme::Rgba;use notepad_core::{LineMetadata,ListType};pub const BULLET:usize=0;pub const SUB_BULLET:usize=1;pub const UNCHECKED:usize=2;pub const CHECKED:usize=3;
pub fn configure(e:&DirectEditor,fg:Rgba,bg:Rgba){for(i,s)in[(BULLET,ffi::SCI_MARK_CIRCLE),(SUB_BULLET,ffi::SCI_MARK_CIRCLE),(UNCHECKED,ffi::SCI_MARK_ROUNDRECT),(CHECKED,ffi::SCI_MARK_ROUNDRECT)]{e.send(ffi::SCI_MARKERDEFINE,i,s as isize);e.send(ffi::SCI_MARKERSETFORE,i,colour(fg));e.send(ffi::SCI_MARKERSETBACK,i,colour(bg))}}pub fn apply(e:&DirectEditor,line:usize,m:&LineMetadata){for i in [BULLET,SUB_BULLET,UNCHECKED,CHECKED]{e.send(ffi::SCI_MARKERDELETE,line,i as isize)}let i=match m.list_type{ListType::None|ListType::Number=>return,ListType::Bullet if m.indent==0=>BULLET,ListType::Bullet=>SUB_BULLET,ListType::Check if m.checked=>CHECKED,ListType::Check=>UNCHECKED};e.send(ffi::SCI_MARKERADD,line,i as isize)}fn colour(c:Rgba)->isize{((c.r as u32)<<16|((c.g as u32)<<8)|c.b as u32)as isize}
